/**
 * Batch 5 — ~110 verified India Quiz questions.
 * 10 per category × 11 categories.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string; categoryId: string; text: string;
  options: [string, string, string, string]; correctIndex: number;
  explanation: string; source: string; difficulty: 'easy'|'medium'|'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk (10) ═══
  { slug: 'gk-nsg-membership-india', categoryId: 'cat-gk', text: 'India became a member of the Nuclear Suppliers Group (NSG) in which year?', options: ['2004', '2008', '2010', 'India is not a member'], correctIndex: 3, explanation: 'India is NOT a member of the Nuclear Suppliers Group (NSG), though it has been seeking membership since 2008. India received a NSG waiver in 2008 allowing nuclear commerce despite not signing the NPT, but full membership remains blocked by China and others.', source: 'Ministry of External Affairs / Nuclear Suppliers Group', difficulty: 'hard' },
  { slug: 'gk-brics-expansion-2024', categoryId: 'cat-gk', text: 'BRICS expanded to include new members in 2024. Which of the following countries joined BRICS in 2024?', options: ['Only Iran', 'Iran, UAE, Egypt, Ethiopia', 'Iran, UAE, Egypt, Ethiopia, and Saudi Arabia (negotiating)', 'No new members joined'], correctIndex: 2, explanation: 'On 1 January 2024, Iran, UAE, Egypt, and Ethiopia officially joined BRICS. Saudi Arabia was invited but its membership status remained under negotiation. The original BRICS members were Brazil, Russia, India, China, and South Africa (South Africa joined in 2010).', source: 'Ministry of External Affairs / BRICS Summit 2023', difficulty: 'medium' },
  { slug: 'gk-g20-presidency-india', categoryId: 'cat-gk', text: 'India hosted the G20 Summit in 2023 in which city?', options: ['Mumbai', 'New Delhi', 'Bengaluru', 'Chennai'], correctIndex: 1, explanation: 'India hosted the G20 Summit on 9-10 September 2023 in New Delhi. India\'s G20 Presidency ran from 1 December 2022 to 30 November 2023. The New Delhi Leaders\' Declaration was adopted at the summit, emphasizing inclusive growth and the African Union\'s inclusion as a permanent G20 member.', source: 'Ministry of External Affairs / G20 India 2023', difficulty: 'easy' },
  { slug: 'gk-india-moonlighting-legal', categoryId: 'cat-gk', text: 'In India, the practice of "moonlighting" (taking a second job while employed) is generally governed by which type of law?', options: ['Constitutional law', 'Employment/labour law and individual employment contracts', 'Criminal law', 'Tax law only'], correctIndex: 1, explanation: 'Moonlighting in India is governed by employment/labour law and individual employment contracts. The Factories Act, 1948 restricts dual employment in factories. Many IT companies include non-compete clauses. The Industrial Employment (Standing Orders) Act, 1946 also regulates employment conditions. There is no specific central law banning moonlighting outright.', source: 'Ministry of Labour and Employment / Industrial Employment (Standing Orders) Act, 1946', difficulty: 'hard' },
  { slug: 'gk-india-quad-members', categoryId: 'cat-gk', text: 'The QUAD (Quadrilateral Security Dialogue) includes India and which three other countries?', options: ['India, USA, UK, Australia', 'India, USA, Japan, Australia', 'India, USA, France, Japan', 'India, USA, Japan, South Korea'], correctIndex: 1, explanation: 'The QUAD comprises India, USA, Japan, and Australia. It was initiated in 2007 and revived in 2017. The QUAD focuses on a "free and open Indo-Pacific." India hosted the QUAD Leaders\' Summit in Tokyo (2022) and Hiroshima (2023). The QUAD is not a military alliance but a strategic dialogue.', source: 'Ministry of External Affairs / QUAD Summit declarations', difficulty: 'medium' },
  { slug: 'gk-scheduled-languages-constitution', categoryId: 'cat-gk', text: 'The 8th Schedule of the Constitution of India recognises how many languages (as of 2024)?', options: ['18', '20', '22', '25'], correctIndex: 2, explanation: 'The 8th Schedule recognises 22 languages. The original Constitution had 14 languages; Sindhi was added by the 21st Amendment (1967), Konkani, Manipuri, and Nepali by the 71st Amendment (1992), and Bodo, Dogri, Maithili, and Santali by the 92nd Amendment (2003).', source: 'Constitution of India, 8th Schedule', difficulty: 'medium' },
  { slug: 'gk-india-largest-festival', categoryId: 'cat-gk', text: 'Which is the largest religious gathering (by number of pilgrims) in the world, held in India?', options: ['Kumbh Mela', 'Hajj pilgrimage', 'Sabarimala pilgrimage', 'Vaishno Devi pilgrimage'], correctIndex: 0, explanation: 'The Kumbh Mela is the largest religious gathering in the world. The 2019 Prayagraj Kumbh Mela attracted approximately 120-150 million pilgrims over 48 days. UNESCO recognised Kumbh Mela as an Intangible Cultural Heritage of Humanity in 2017.', source: 'UNESCO Intangible Cultural Heritage / Ministry of Culture', difficulty: 'easy' },
  { slug: 'gk-india-aadhaar-number-digits', categoryId: 'cat-gk', text: 'The Aadhaar number issued by UIDAI consists of how many digits?', options: ['10', '12', '14', '16'], correctIndex: 1, explanation: 'The Aadhaar number is a 12-digit unique identity number issued by UIDAI (Unique Identification Authority of India) to Indian residents. It was launched in 2009. The first Aadhaar was issued on 29 September 2010. Over 1.35 billion Aadhaar numbers have been generated.', source: 'UIDAI, Government of India', difficulty: 'easy' },
  { slug: 'gk-india-largest-bank-2024', categoryId: 'cat-gk', text: 'As of 2024, which is the largest bank in India by total assets?', options: ['ICICI Bank', 'HDFC Bank', 'State Bank of India (SBI)', 'Punjab National Bank'], correctIndex: 2, explanation: 'State Bank of India (SBI) is the largest bank in India by total assets (approximately Rs. 60+ lakh crore as of 2024). SBI was established in 1955. HDFC Bank is the largest private sector bank. Following the HDFC-HDFC Bank merger (July 2022), HDFC Bank became one of the world\'s top 10 banks by market capitalisation.', source: 'Reserve Bank of India / State Bank of India', difficulty: 'medium' },
  { slug: 'gk-india-census-commissioner-office', categoryId: 'cat-gk', text: 'The Census of India is conducted by which office, under which ministry?', options: ['Election Commission, under Ministry of Law', 'Registrar General & Census Commissioner, under Ministry of Home Affairs', 'Statistics Office, under Ministry of Statistics', 'Planning Commission, under PMO'], correctIndex: 1, explanation: 'The Census of India is conducted by the Office of the Registrar General & Census Commissioner, under the Ministry of Home Affairs. It operates under the Census Act, 1948. The last completed census was in 2011; the 2021 Census was postponed due to COVID-19.', source: 'Office of the Registrar General & Census Commissioner / Ministry of Home Affairs', difficulty: 'medium' },

  // ═══ cat-history (10) ═══
  { slug: 'hist-harappan-seals-pashupati', categoryId: 'cat-history', text: 'The famous "Pashupati Seal" from Mohenjo-daro depicts a figure surrounded by which animals?', options: ['Lions, tigers, and elephants', 'Elephant, tiger, rhino, and buffalo', 'Bulls, horses, and goats', 'Deer, monkeys, and snakes'], correctIndex: 1, explanation: 'The Pashupati Seal (c. 2000 BCE) depicts a horned figure seated in a yogic posture, surrounded by an elephant, tiger, rhinoceros, and buffalo. Two deer appear at the base. The figure may represent a proto-Shiva or a deity associated with yoga and wildlife.', source: 'Archaeological Survey of India / National Museum, New Delhi', difficulty: 'hard' },
  { slug: 'hist-buddha-four-noble-truths-count', categoryId: 'cat-history', text: 'Buddhism is founded on the Four Noble Truths. These were first preached by Buddha at which location?', options: ['Bodh Gaya', 'Sarnath (Deer Park)', 'Kushinagar', 'Lumbini'], correctIndex: 1, explanation: 'Buddha first preached the Four Noble Truths at the Deer Park in Sarnath (near Varanasi), approximately 5 weeks after his enlightenment at Bodh Gaya. This event is called "Dharmachakra Pravartana" (Turning the Wheel of Dharma) and forms the foundation of Buddhist teaching.', source: 'Archaeological Survey of India / UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'hist-delhi-sultanate-five-dynasties', categoryId: 'cat-history', text: 'The Delhi Sultanate (1206-1526 CE) was ruled by how many successive dynasties?', options: ['Three', 'Four', 'Five', 'Six'], correctIndex: 2, explanation: 'The Delhi Sultanate was ruled by five successive dynasties: Mamluk/Slave Dynasty (1206-1290), Khalji (1290-1320), Tughlaq (1320-1414), Sayyid (1414-1451), and Lodi (1451-1526). It was ended by Babur\'s victory at the First Battle of Panipat (1526), founding the Mughal Empire.', source: 'Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-mughal-akbar-todarmal-revenue', categoryId: 'cat-history', text: 'Raja Todar Mal, Akbar\'s revenue minister, is famous for implementing which land revenue system?', options: ['Zabt system (standardised land measurement and revenue collection)', 'Zamindari system', 'Ryotwari system', 'Mahalwari system'], correctIndex: 0, explanation: 'Raja Todar Mal implemented the Zabt system (also called Ain-i-Dahsala), which standardised land measurement (bigha) and revenue collection based on average produce and prices over 10 years. This brought efficiency to Mughal revenue administration. He was one of Akbar\'s "Navaratnas."', source: 'Indian Council of Historical Research / Abul Fazl\'s Akbarnama', difficulty: 'medium' },
  { slug: 'hist-bhakti-saint-rajamanda', categoryId: 'cat-history', text: 'The Bhakti saint Ramananda (14th century) was a follower of which earlier saint\'s philosophical tradition?', options: ['Shankaracharya (Advaita Vedanta)', 'Ramanujacharya (Vishishtadvaita Vedanta)', 'Madhvacharya (Dvaita Vedanta)', 'Vallabhacharya (Shuddhadvaita)'], correctIndex: 1, explanation: 'Ramananda (c. 1400-1470) was a follower of Ramanujacharya\'s Vishishtadvaita tradition. He later founded the Ramanandi sect, which popularised Bhakti in North India. He was the teacher of Kabir, Ravidas, and Pipa. He broke caste barriers by accepting disciples from all castes.', source: 'Sahitya Akademi / Indian Council of Historical Research', difficulty: 'hard' },
  { slug: 'hist-first-war-independence-date', categoryId: 'cat-history', text: 'The Revolt of 1857 (First War of Independence) officially began on which date?', options: ['10 May 1857', '29 March 1857', '2 June 1857', '8 April 1857'], correctIndex: 0, explanation: 'The Revolt of 1857 began on 10 May 1857 when Indian sepoys at Meerut mutinied, killed British officers, and marched to Delhi. The immediate trigger was the Enfield rifle cartridge grease rumour (pork/beef fat). Mangal Pandey\'s revolt at Barrackpore on 29 March 1857 was a precursor.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-swaraj-party-founders', categoryId: 'cat-history', text: 'The Swaraj Party was formed in 1923 by whom, within the Indian National Congress?', options: ['Gandhi and Patel', 'Motilal Nehru and C.R. Das', 'Jawaharlal Nehru and Subhas Bose', 'Tilak and Gokhale'], correctIndex: 1, explanation: 'The Swaraj Party was formed in 1923 by Motilal Nehru and C.R. Das (Chittaranjan Das) after the withdrawal of the Non-Cooperation Movement. The party aimed to enter the legislative councils to obstruct British rule from within, opposing Gandhi\'s policy of council boycott.', source: 'Indian Council of Historical Research / Indian National Congress Archives', difficulty: 'medium' },
  { slug: 'hist-ina-trials-red-fort', categoryId: 'cat-history', text: 'The famous INA (Indian National Army) trials were held at which location in 1945-46?', options: ['Bombay High Court', 'Red Fort, Delhi', 'Lahore Fort', 'Calcutta High Court'], correctIndex: 1, explanation: 'The INA trials (also called the Red Fort Trials) were held at the Red Fort, Delhi, in November 1945. The British tried INA officers — Colonel Prem Sahgal, Colonel Gurbaksh Singh Dhillon, and Major General Shah Nawaz Khan — for "waging war against the King." The trials sparked massive public sympathy for the INA across India.', source: 'National Archives of India', difficulty: 'medium' },
  { slug: 'hist-princely-states-count-1947', categoryId: 'cat-history', text: 'At the time of India\'s independence in 1947, approximately how many princely states existed?', options: ['About 200', 'About 350', 'About 565', 'About 1,000'], correctIndex: 2, explanation: 'There were approximately 565 princely states in British India at the time of independence. Sardar Vallabhbhai Patel, as Home Minister, led the integration of these states into India through diplomacy and, where necessary, force (e.g., Junagadh, Hyderabad, and Goa). The last major state to join was Sikkim (1975, by referendum).', source: 'Ministry of Home Affairs / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-panch-sheel-principles-count', categoryId: 'cat-history', text: 'The Panchsheel (Five Principles of Peaceful Coexistence) were enunciated in a treaty between India and which country in 1954?', options: ['Soviet Union', 'China', 'United States', 'Indonesia'], correctIndex: 1, explanation: 'The Panchsheel (Five Principles of Peaceful Coexistence) were enshrined in the "Agreement on Trade and Intercourse between the Tibet Region of China and India" signed on 29 April 1954. The five principles: mutual respect for territorial integrity, mutual non-aggression, mutual non-interference, equality and cooperation, and peaceful coexistence.', source: 'Ministry of External Affairs / Panchsheel Treaty, 1954', difficulty: 'medium' },

  // ═══ cat-geography (10) ═══
  { slug: 'geo-india-coastline-states-count', categoryId: 'cat-geography', text: 'How many Indian states and Union Territories have a coastline?', options: ['6 states + 2 UTs', '7 states + 3 UTs', '8 states + 3 UTs', '9 states + 4 UTs'], correctIndex: 3, explanation: '9 states (Gujarat, Maharashtra, Goa, Karnataka, Kerala, Tamil Nadu, Andhra Pradesh, Odisha, West Bengal) and 4 UTs (Daman & Diu/Dadra & Nagar Haveli, Lakshadweep, Andaman & Nicobar Islands, Puducherry) have coastlines. Gujarat has the longest coastline among states.', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-forest-policy-target', categoryId: 'cat-geography', text: 'The National Forest Policy of India aims to bring what percentage of the geographical area under forest cover?', options: ['21%', '25%', '33%', '50%'], correctIndex: 2, explanation: 'The National Forest Policy, 1988 aims to bring 33% (one-third) of India\'s geographical area under forest/tree cover. Currently, India\'s forest cover is approximately 21.71% (India State of Forest Report 2021). The target is to bridge the gap through afforestation and conservation.', source: 'Ministry of Environment, Forest and Climate Change / National Forest Policy 1988', difficulty: 'medium' },
  { slug: 'geo-delta-largest-india', categoryId: 'cat-geography', text: 'Which is the largest river delta in India?', options: ['Mahanadi Delta', 'Godavari Delta', 'Ganga-Brahmaputra (Sundarbans) Delta', 'Krishna Delta'], correctIndex: 2, explanation: 'The Ganga-Brahmaputra Delta (Sundarbans Delta) is the largest river delta in India and the world. It covers approximately 100,000 sq km across India (West Bengal) and Bangladesh. The Sundarbans is a UNESCO World Heritage Site and the world\'s largest mangrove forest.', source: 'Geological Survey of India / UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'geo-deserts-india-two', categoryId: 'cat-geography', text: 'India has two desert regions. The Thar Desert is in Rajasthan. The cold desert is located in which region?', options: ['Spiti Valley, Himachal Pradesh', 'Ladakh (Trans-Himalayan region)', 'Nubra Valley, Kashmir', 'Zanskar Valley, Ladakh'], correctIndex: 1, explanation: 'The cold desert in India is the Trans-Himalayan region, primarily Ladakh. It lies in the rain shadow of the Himalayas, receiving less than 100 mm annual precipitation. Spiti Valley in Himachal Pradesh is another cold desert area. Ladakh has extreme temperatures ranging from +35°C to -30°C.', source: 'Geological Survey of India / Ministry of Tourism', difficulty: 'medium' },
  { slug: 'geo-river-island-largest', categoryId: 'cat-geography', text: 'Majuli, recognised as the world\'s largest river island, is located in which Indian state?', options: ['West Bengal', 'Bihar', 'Assam', 'Arunachal Pradesh'], correctIndex: 2, explanation: 'Majuli is the world\'s largest river island, located in the Brahmaputra River in Assam. It covers approximately 352 sq km (originally ~1,250 sq km, reduced by erosion). Majuli is a centre of neo-Vaishnavite culture established by Srimanta Sankardev. It was declared a district in 2016.', source: 'Ministry of Culture / Assam Tourism / Guinness World Records', difficulty: 'medium' },
  { slug: 'geo-india-longest-river-peninsular', categoryId: 'cat-geography', text: 'Which is the longest river in peninsular India?', options: ['Godavari', 'Krishna', 'Kaveri (Cauvery)', 'Mahanadi'], correctIndex: 0, explanation: 'The Godavari is the longest river in peninsular India, at approximately 1,465 km. It originates in Trimbakeshwar, Maharashtra, and flows eastward into the Bay of Bengal. The Godavari is also called "Dakshin Ganga" (Ganga of the South) due to its length and significance.', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'medium' },
  { slug: 'geo-glaciers-siachen-importance', categoryId: 'cat-geography', text: 'Why is the Siachen Glacier strategically important for India?', options: ['It contains large mineral deposits', 'It overlooks key strategic routes between Pakistan and China (Karakoram Pass)', 'It is a source of fresh water for major cities', 'It has significant oil reserves'], correctIndex: 1, explanation: 'The Siachen Glacier is strategically important because it overlooks the strategic routes between Pakistan-occupied Kashmir and China\'s Shaksgam Valley (ceded by Pakistan to China in 1963). Control of Siachen prevents Pakistan from linking with China via the Karakoram Pass. India has maintained military presence there since Operation Meghdoot (1984).', source: 'Ministry of Defence / Indian Army', difficulty: 'hard' },
  { slug: 'geo-geological-age-deccan-trap', categoryId: 'cat-geography', text: 'The Deccan Traps were formed by massive volcanic eruptions approximately how many million years ago?', options: ['About 10 million years ago', 'About 35 million years ago', 'About 66 million years ago', 'About 250 million years ago'], correctIndex: 2, explanation: 'The Deccan Traps were formed approximately 66 million years ago, near the Cretaceous-Paleogene (K-Pg) boundary. The massive volcanic eruptions released vast quantities of basalt lava, covering about 500,000 sq km. This event is believed to have contributed to the mass extinction that killed the dinosaurs.', source: 'Geological Survey of India', difficulty: 'hard' },
  { slug: 'geo-india-north-south-extent', categoryId: 'cat-geography', text: 'The north-south extent of India (from Kashmir to Kanyakumari) is approximately how many kilometres?', options: ['About 1,500 km', 'About 2,000 km', 'About 3,200 km', 'About 4,500 km'], correctIndex: 2, explanation: 'The north-south extent of India from Kashmir to Kanyakumari is approximately 3,214 km (about 3,200 km). The east-west extent (from Gujarat to Arunachal Pradesh) is approximately 2,933 km. India lies entirely in the Northern Hemisphere.', source: 'Survey of India / Ministry of Home Affairs', difficulty: 'medium' },
  { slug: 'geo-india-ist-meridian', categoryId: 'cat-geography', text: 'Indian Standard Time (IST) is calculated based on the meridian passing through which city?', options: ['Mirzapur (near Allahabad/Prayagraj), Uttar Pradesh', 'Nagpur, Maharashtra', 'Jabalpur, Madhya Pradesh', 'Delhi'], correctIndex: 0, explanation: 'IST is calculated from the 82.5°E meridian, which passes through Mirzapur (near Allahabad/Prayagraj) in Uttar Pradesh. IST is UTC+5:30. The time zone was established in 1906 during British rule. Despite India\'s large east-west span (~30° of longitude), India uses a single time zone.', source: 'India Meteorological Department / Survey of India', difficulty: 'medium' },

  // ═══ cat-civics (10) ═══
  { slug: 'civ-const-amendments-count-2024', categoryId: 'cat-civics', text: 'As of 2024, how many Constitutional Amendments have been made to the Indian Constitution (not counting the Constitution itself, which was the "0th" amendment)?', options: ['About 75', 'About 85', 'About 105-106', 'About 125'], correctIndex: 2, explanation: 'As of 2024, approximately 106 Constitutional Amendments have been made to the Indian Constitution. The most recent significant amendment is the 106th Amendment (2023), which added Article 33A(2) regarding the right to keep personal data private. The 1st Amendment was in 1951; the 42nd (1976, "mini-Constitution") was the most extensive.', source: 'Constitution of India / Parliament of India', difficulty: 'hard' },
  { slug: 'civ-const-preamble-words-socialism', categoryId: 'cat-civics', text: 'The words "Socialist" and "Secular" were added to the Preamble of the Indian Constitution by which Amendment?', options: ['1st Amendment (1951)', '42nd Amendment (1976)', '44th Amendment (1978)', '52nd Amendment (1985)'], correctIndex: 1, explanation: 'The words "Socialist" and "Secular" were added to the Preamble by the 42nd Constitutional Amendment Act, 1976, during the Emergency. The original Preamble (1950) described India as a "Sovereign Democratic Republic." The 42nd Amendment changed it to "Sovereign Socialist Secular Democratic Republic."', source: 'Constitution of India, 42nd Amendment Act / Parliament of India', difficulty: 'medium' },
  { slug: 'civ-president-rule-article-356', categoryId: 'cat-civics', text: 'President\'s Rule under Article 356 is imposed when what situation arises in a state?', options: ['The Chief Minister resigns', 'The Governor recommends it', 'The constitutional machinery of the state fails', 'Elections are delayed'], correctIndex: 2, explanation: 'Article 356 empowers the President to impose President\'s Rule in a state when the constitutional machinery fails. The state government is dismissed, and the Governor administers the state on behalf of the President. It has been invoked over 130 times since 1950, often controversially.', source: 'Constitution of India, Article 356', difficulty: 'medium' },
  { slug: 'civ-fundamental-duty-added-86th', categoryId: 'cat-civics', text: 'The 86th Constitutional Amendment (2002) added which Fundamental Duty?', options: ['To protect the environment', 'To provide education to children aged 6-14 years', 'To vote in elections', 'To pay taxes'], correctIndex: 1, explanation: 'The 86th Constitutional Amendment Act, 2002 added Article 21A (Right to Education for children aged 6-14 as a Fundamental Right) and added a corresponding Fundamental Duty under Article 51A(k): "a parent or guardian to provide opportunities for education to his child or ward between 6 and 14 years of age."', source: 'Constitution of India, 86th Amendment Act, 2002', difficulty: 'medium' },
  { slug: 'civ-fundamental-rights-article-21-expanded', categoryId: 'cat-civics', text: 'Article 21 ("Right to Life and Personal Liberty") has been expansively interpreted by the Supreme Court. Which of the following has been held to fall under Article 21?', options: ['Right to property only', 'Right to clean environment, privacy, education, and dignity', 'Right to free speech only', 'Right to religious freedom'], correctIndex: 1, explanation: 'The Supreme Court has interpreted Article 21 expansively. It includes the right to clean environment (M.C. Mehta cases), right to privacy (Puttaswamy v. Union of India, 2017), right to education (before the 86th Amendment), right to live with dignity (Maneka Gandhi case, 1978), right to health, right to shelter, and right to a fair trial.', source: 'Supreme Court of India / Constitution of India, Article 21', difficulty: 'medium' },
  { slug: 'civ-state-legislative-council-abolition', categoryId: 'cat-civics', text: 'Under Article 169, the Legislative Council (Vidhan Parishad) of a state can be abolished by Parliament if what condition is met?', options: ['The Governor recommends it', 'The State Legislative Assembly passes a resolution by special majority', 'The President directs it', 'Parliament passes a simple resolution'], correctIndex: 1, explanation: 'Under Article 169, Parliament may abolish a state\'s Legislative Council if the State Legislative Assembly passes a resolution by a special majority (2/3 of members present and voting, plus a majority of the total membership). Andhra Pradesh abolished its Legislative Council in 1985 (re-established 2007). Tamil Nadu also abolished its council.', source: 'Constitution of India, Article 169', difficulty: 'hard' },
  { slug: 'civ-anti-defection-disqualification-speaker', categoryId: 'cat-civics', text: 'Under the Anti-Defection Law (Tenth Schedule), who has the authority to decide on disqualification of a member?', options: ['The President of India', 'The Speaker/Chairman of the House', 'The Election Commission', 'The Chief Justice of India'], correctIndex: 1, explanation: 'Under the Tenth Schedule (added by the 52nd Amendment, 1985), the Speaker of the Lok Sabha/State Legislative Assembly or the Chairman of the Rajya Sabha/State Legislative Council has the authority to decide on disqualification of a member for defection. The Speaker\'s decision is subject to judicial review (Kihoto Hollohan case, 1992).', source: 'Constitution of India, Tenth Schedule', difficulty: 'medium' },
  { slug: 'civ-gst-council-voting', categoryId: 'cat-civics', text: 'In the GST Council, voting requires what quorum and what majority for decisions?', options: ['1/2 members present; simple majority', '1/2 members present; 3/4 majority of present and voting', '1/3 members present; 2/3 majority', 'Full membership required; simple majority'], correctIndex: 1, explanation: 'Under Article 279A(9), GST Council decisions require a quorum of half the total members and a 3/4 majority of the present and voting members. The Centre has 1/3 of the votes and the States collectively have 2/3. This ensures both the Centre and States must agree on decisions.', source: 'Constitution of India, Article 279A(9) / GST Council', difficulty: 'hard' },
  { slug: 'civ-reservation-sc-st-const', categoryId: 'cat-civics', text: 'Reservation of seats for SCs and STs in the Lok Sabha and State Assemblies was originally for how many years?', options: ['10 years', '20 years', '30 years', '50 years'], correctIndex: 0, explanation: 'Article 334 originally provided reservation of seats for SCs and STs for 10 years (till 1960). It has been extended multiple times. The 104th Amendment (2019) extended it for another 10 years (till 25 January 2030). Reservation for Anglo-Indians (2 seats in Lok Sabha) was abolished by the same amendment.', source: 'Constitution of India, Article 334 / 104th Amendment Act, 2019', difficulty: 'medium' },
  { slug: 'civ-special-provision-delhi-art-239aa', categoryId: 'cat-civics', text: 'The special status of the National Capital Territory of Delhi is provided under which Article?', options: ['Article 239A', 'Article 239AA', 'Article 240', 'Article 370'], correctIndex: 1, explanation: 'Article 239AA provides the special status of Delhi as a Union Territory with a Legislative Assembly. It was inserted by the 69th Constitutional Amendment (1991). The Delhi Assembly can make laws on all subjects in the State List and Concurrent List except public order, police, and land — which remain with the Centre.', source: 'Constitution of India, Article 239AA / 69th Amendment Act, 1991', difficulty: 'hard' },

  // ═══ cat-science (10) ═══
  { slug: 'sci-isro-gslv-mk3-lvm3-significance', categoryId: 'cat-science', text: 'LVM3 (formerly GSLV Mk III) is significant because it can carry payloads of approximately how many tonnes to Low Earth Orbit (LEO)?', options: ['About 4 tonnes', 'About 8-10 tonnes', 'About 15 tonnes', 'About 20 tonnes'], correctIndex: 1, explanation: 'LVM3 can carry approximately 8-10 tonnes to Low Earth Orbit (LEO) and about 4 tonnes to Geosynchronous Transfer Orbit (GTO). It is ISRO\'s heaviest launch vehicle and the first to use an indigenous cryogenic upper stage. LVM3 launched Chandrayaan-2, Chandrayaan-3, and Aditya-L1.', source: 'ISRO official website / Department of Space', difficulty: 'medium' },
  { slug: 'sci-india-nuclear-tests-pokhran-2-weapons', categoryId: 'cat-science', text: 'India\'s Pokhran-II nuclear tests (May 1998) consisted of how many test explosions?', options: ['3', '5', '7', '10'], correctIndex: 1, explanation: 'Pokhran-II consisted of 5 nuclear test explosions conducted on 11 and 13 May 1998 at the Pokhran test range in Rajasthan. The tests included a thermonuclear device (Shakti-I), three fission devices, and one sub-kiloton device. India declared itself a nuclear-weapon state after these tests.', source: 'Department of Atomic Energy, Government of India', difficulty: 'medium' },
  { slug: 'sci-isro-antrix-commercial-arm', categoryId: 'cat-science', text: 'Which ISRO entity handles commercial space business (satellite launches, data sales)?', options: ['NewSpace India Limited (NSIL)', 'Antrix Corporation', 'Both NSIL and Antrix', 'ISRO directly'], correctIndex: 2, explanation: 'ISRO has two commercial arms: Antrix Corporation (established 1992, handles international commercial satellite launches and data) and NewSpace India Limited / NSIL (established 2019, handles domestic commercial launches, technology transfer, and satellite building). NSIL launched GSAT-24 (2022) on an Ariane 5 rocket — its first commercial satellite mission.', source: 'Department of Space / NSIL / Antrix Corporation', difficulty: 'hard' },
  { slug: 'sci-solar-rooftop-india-target', categoryId: 'cat-science', text: 'India\'s PM Surya Ghar: Muft Bijli Yojana (launched 2024) aims to install rooftop solar on how many households?', options: ['1 million', '5 million', '10 million', '50 million'], correctIndex: 2, explanation: 'PM Surya Ghar: Muft Bijli Yojana was launched on 13 February 2024. It aims to install rooftop solar panels on 10 million (1 crore) households. The scheme provides up to 300 units of free electricity per month and subsidies of up to Rs. 78,000 for installation. The total outlay is over Rs. 75,000 crore.', source: 'Ministry of New and Renewable Energy (MNRE)', difficulty: 'medium' },
  { slug: 'sci-indian-scientist-cv-raman-effect-year', categoryId: 'cat-science', text: 'C.V. Raman discovered the "Raman Effect" (scattering of light) in which year?', options: ['1905', '1918', '1928', '1930'], correctIndex: 2, explanation: 'Sir C.V. Raman discovered the "Raman Effect" (inelastic scattering of light by molecules) on 28 February 1928 at the Indian Association for the Cultivation of Science, Kolkata. He received the Nobel Prize in Physics in 1930 for this discovery — the first Asian to receive a Nobel in science. February 28 is celebrated as National Science Day.', source: 'Indian National Science Academy (INSA) / Nobel Prize Foundation', difficulty: 'medium' },
  { slug: 'sci-indian-mathematician-bhaskara-2-leap', categoryId: 'cat-science', text: 'Bhaskara II (12th century) is famous for which mathematical concept, among others?', options: ['Invention of calculus', 'Concept of instantaneous motion (early calculus) and solutions to Pell\'s equation', 'Proof of Fermat\'s Last Theorem', 'Invention of logarithms'], correctIndex: 1, explanation: 'Bhaskara II (1114-1185 CE), author of "Siddhanta Shiromani," discussed concepts of instantaneous motion (precursors to differential calculus), solved Pell\'s equation (Nx²+1=y²), and gave the concept of gravitational force centuries before Newton. His work "Lilavati" on arithmetic is one of the most famous mathematical texts in Indian history.', source: 'Indian National Science Academy / Encyclopaedia Britannica', difficulty: 'hard' },
  { slug: 'sci-indian-green-revolution-state-first', categoryId: 'cat-science', text: 'The Green Revolution in India was first implemented in which state?', options: ['Punjab', 'Haryana', 'Uttar Pradesh', 'Bihar'], correctIndex: 0, explanation: 'The Green Revolution was first implemented in Punjab (and parts of Haryana) in the mid-1960s. High-Yielding Variety (HYV) seeds of wheat (developed by Norman Borlaug, who won the Nobel Peace Prize in 1970) were introduced, along with chemical fertilizers and irrigation, dramatically increasing wheat production.', source: 'Indian Council of Agricultural Research (ICAR) / Ministry of Agriculture', difficulty: 'medium' },
  { slug: 'sci-covid-vaccination-india-doses', categoryId: 'cat-science', text: 'India\'s COVID-19 vaccination drive (launched 16 January 2021) administered approximately how many doses by mid-2024?', options: ['About 1 billion', 'About 1.5 billion', 'About 2.2 billion', 'About 5 billion'], correctIndex: 2, explanation: 'India\'s COVID-19 vaccination drive, launched on 16 January 2021, administered approximately 2.2 billion doses by mid-2024. India used Covishield (Serum Institute/AstraZeneca), Covaxin (Bharat Biotech), and Corbevax/Sputnik V. India also exported/donated vaccines to 100+ countries under "Vaccine Maitri."', source: 'Ministry of Health and Family Welfare / CoWin Portal', difficulty: 'medium' },
  { slug: 'sci-isro-space-docking-2024', categoryId: 'cat-science', text: 'ISRO\'s SpaDeX (Space Docking Experiment) mission, launched in 2024, aims to demonstrate which capability?', options: ['Lunar landing', 'Space docking (joining two spacecraft in orbit)', 'Mars orbit insertion', 'Human spaceflight'], correctIndex: 1, explanation: 'SpaDeX (Space Docking Experiment) aims to demonstrate India\'s capability to dock two spacecraft in orbit — a critical technology for future human spaceflight (Gaganyaan), space station construction, and satellite servicing. ISRO launched two small spacecraft (SDX-01 and SDX-02) to test rendezvous, docking, and undocking.', source: 'ISRO official website / Department of Space', difficulty: 'hard' },
  { slug: 'sci-drdo-lca-tejas-combat-proven', categoryId: 'cat-science', text: 'The HAL Tejas Light Combat Aircraft (LCA) achieved which significant milestone in 2016?', options: ['First flight', 'Initial Operational Clearance (IOC)', 'Final Operational Clearance (FOC)', 'Combat deployment in the Air Force'], correctIndex: 1, explanation: 'The HAL Tejas achieved Initial Operational Clearance (IOC) in 2016 and Final Operational Clearance (FOC) in 2019. The IAF has inducted two squadrons (No. 45 "Flying Daggers" and No. 18 "Flying Bullets"). The Tejas is the first indigenously designed and manufactured fighter aircraft in the IAF.', source: 'DRDO / HAL / Indian Air Force', difficulty: 'medium' },

  // ═══ cat-sports (10) ═══
  { slug: 'spt-olympic-india-2024-hockey-bronze', categoryId: 'cat-sports', text: 'The Indian men\'s hockey team won back-to-back Olympic bronze medals at Tokyo 2020 and Paris 2024. Who scored the winning goal in the Paris 2024 bronze medal match?', options: ['Mandeep Singh', 'Harmanpreet Singh', 'Raj Kumar Pal', 'Gurjant Singh'], correctIndex: 1, explanation: 'India defeated Spain 2-1 in the Paris 2024 bronze medal match. Harmanpreet Singh (captain) scored a brace (2 goals), including the match-winner. This was India\'s second consecutive Olympic bronze. The Indian hockey team has won 13 Olympic medals (8 gold, 1 silver, 4 bronze).', source: 'International Hockey Federation (FIH) / Hockey India', difficulty: 'hard' },
  { slug: 'spt-cricket-india-test-bowlers-500', categoryId: 'cat-sports', text: 'Which Indian bowler became the first to take 500 wickets in Test cricket?', options: ['Anil Kumble', 'Kapil Dev', 'Harbhajan Singh', 'Zaheer Khan'], correctIndex: 0, explanation: 'Anil Kumble became the first Indian bowler to take 500 Test wickets in 2006, during the third Test against England at Mohali. He finished with 619 wickets in 132 Tests. Only Muttiah Muralitharan (800), Shane Warne (708), and James Anderson (700+) have more Test wickets.', source: 'ESPN Cricinfo / ICC records / BCCI', difficulty: 'medium' },
  { slug: 'spt-india-archery-deepika-kumari-world-no1', categoryId: 'cat-sports', text: 'Deepika Kumari became world No.1 in women\'s recurve archery in which year (the first Indian to achieve this)?', options: ['2012', '2015', '2021', '2023'], correctIndex: 2, explanation: 'Deepika Kumari became world No.1 in women\'s recurve archery in June 2021, after winning three gold medals at the World Archery World Cup Stage 3 in Paris. She was the first Indian archer (male or female) to achieve the world No.1 ranking in recurve archery.', source: 'World Archery / Archery Association of India', difficulty: 'hard' },
  { slug: 'spt-badminton-thomas-cup-india-2022-final', categoryId: 'cat-sports', text: 'India defeated which country 3-0 in the final to win its first Thomas Cup (men\'s badminton team championship) in 2022?', options: ['China', 'Indonesia', 'Malaysia', 'Denmark'], correctIndex: 1, explanation: 'India defeated Indonesia 3-0 in the final of the Thomas Cup 2022 in Bangkok. Lakshya Sen won the first singles, Satwiksairaj Rankireddy and Chirag Shetty won the doubles, and Kidambi Srikanth won the second singles. This was India\'s first Thomas Cup title since the tournament began in 1949.', source: 'Badminton World Federation (BWF) / Badminton Association of India', difficulty: 'medium' },
  { slug: 'spt-chess-world-cup-2024-gukesh', categoryId: 'cat-sports', text: 'In 2024, which Indian chess player became the youngest-ever World Chess Championship challenger by winning the Candidates Tournament?', options: ['Rameshbabu Praggnanandhaa', 'Dommaraju Gukesh', 'Arjun Erigaisi', 'Nihal Sarin'], correctIndex: 1, explanation: 'Dommaraju Gukesh (born 2006) won the FIDE Candidates Tournament in April 2024, becoming the youngest-ever challenger for the World Chess Championship. He earned the right to challenge Ding Liren for the World Chess Championship title. Gukesh also became the youngest player to cross a 2800 FIDE rating in 2023.', source: 'World Chess Federation (FIDE)', difficulty: 'medium' },
  { slug: 'spt-paris-2024-shooting-manu-bhaker', categoryId: 'cat-sports', text: 'Manu Bhaker became the first Indian woman to win two medals at a single Olympics (Paris 2024). In which events did she win?', options: ['10m air pistol (bronze) and 10m air pistol mixed team (bronze)', '25m pistol (gold) and 10m air pistol (silver)', '50m rifle 3 positions (bronze) and 10m air rifle (bronze)', '10m air pistol (gold) and 25m pistol (bronze)'], correctIndex: 0, explanation: 'Manu Bhaker won bronze in the 10m air pistol event and bronze in the 10m air pistol mixed team event (with Sarabjot Singh) at the Paris 2024 Olympics. She became the first Indian woman to win two Olympic medals in a single edition and the first Indian shooter to win two medals at one Olympics.', source: 'International Olympic Committee (IOC) / National Rifle Association of India', difficulty: 'medium' },
  { slug: 'spt-cricket-2007-t20-world-cup-six', categoryId: 'cat-sports', text: 'In the 2007 T20 World Cup final, India vs Pakistan, who hit the famous six off the last ball to win the match?', options: ['MS Dhoni', 'Yuvraj Singh', 'Sreesanth', 'Joginder Sharma'], correctIndex: 3, explanation: 'Joginder Sharma bowled the last over of the 2007 T20 World Cup final. Pakistan needed 6 runs off 4 balls. Misbah-ul-Haq tried a scoop shot on the third ball and was caught by Sreesanth. India won the match by 5 runs. Joginder Sharma was the bowler, not the batsman.', source: 'ICC T20 World Cup records / ESPN Cricinfo', difficulty: 'medium' },
  { slug: 'spt-wrestling-sakshi-malik-2016', categoryId: 'cat-sports', text: 'Sakshi Malik won India\'s first Olympic wrestling medal by a woman. At which Olympics and in what weight category?', options: ['London 2012, 55 kg', 'Rio 2016, 58 kg freestyle', 'Tokyo 2020, 57 kg', 'Paris 2024, 53 kg'], correctIndex: 1, explanation: 'Sakshi Malik won bronze in the 58 kg freestyle wrestling at the Rio 2016 Olympics. She became the first Indian female wrestler to win an Olympic medal. She defeated Aisuluu Tynybekova of Kyrgyzstan in the bronze medal match. She is from Rohtak, Haryana, and was awarded the Rajiv Gandhi Khel Ratna (now Major Dhyan Chand Khel Ratna) in 2016.', source: 'International Olympic Committee (IOC) / Wrestling Federation of India', difficulty: 'medium' },
  { slug: 'spt-athletics-anju-bobby-george', categoryId: 'cat-sports', text: 'Anju Bobby George became the first Indian athlete to win a medal at the World Athletics Championships. In which event and year?', options: ['Long jump, 2003 (Paris)', 'Triple jump, 2003 (Paris)', 'High jump, 2005 (Helsinki)', 'Long jump, 2007 (Osaka)'], correctIndex: 0, explanation: 'Anju Bobby George won bronze in the long jump at the 2003 World Athletics Championships in Paris, becoming the first Indian athlete to win a World Championship medal. She jumped 6.70 m. She also won gold at the 2002 Busan Asian Games and was awarded the Khel Ratna in 2003.', source: 'World Athletics / Athletics Federation of India', difficulty: 'hard' },
  { slug: 'spt-football-sunil-chhetri-goals', categoryId: 'cat-sports', text: 'Sunil Chhetri, India\'s most capped footballer, retired in 2024 with how many international goals (approximately)?', options: ['About 50', 'About 75', 'About 94', 'About 110'], correctIndex: 2, explanation: 'Sunil Chhetri retired from international football in June 2024 with 94 international goals from 151 matches. At the time of his retirement, he was the 4th highest international goalscorer in football history, behind Cristiano Ronaldo, Lionel Messi, and Ali Daei. He scored his last goal against Kuwait in his final match.', source: 'All India Football Federation (AIFF) / FIFA', difficulty: 'medium' },

  // ═══ cat-culture (10) ═══
  { slug: 'cul-hampi-virupaksha-patron', categoryId: 'cat-culture', text: 'The Virupaksha Temple at Hampi was significantly expanded by which ruler of the Vijayanagara Empire?', options: ['Krishnadevaraya', 'Deva Raya II', 'Harihara I', 'Bukka Raya I'], correctIndex: 0, explanation: 'The Virupaksha Temple (dedicated to Shiva as Virupaksha) was significantly expanded by Krishnadevaraya (r. 1509-1529), the greatest ruler of the Vijayanagara Empire. He added the ornate eastern gopuram (tower) and the pillared halls. The temple pre-dates the Vijayanagara Empire and has been continuously worshipped at for over 1,400 years.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-fatehpur-sikri-buland-darwaza-height', categoryId: 'cat-culture', text: 'The Buland Darwaza (Grand Gate) at Fatehpur Sikri is approximately how tall?', options: ['About 30 m', 'About 40 m (134 feet)', 'About 55 m', 'About 70 m'], correctIndex: 1, explanation: 'The Buland Darwaza is approximately 40 m (134 feet) tall, making it one of the tallest gateways in the world. It was built by Akbar in 1601 to commemorate his victory over Gujarat. The gateway is made of red sandstone with white marble inlay and is approached by a flight of 42 steps.', source: 'Archaeological Survey of India / UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'cul-kerala-backwaters-houseboats', categoryId: 'cat-culture', text: 'The traditional Kerala houseboat is called by what name?', options: ['Shikara', 'Kettuvallam', 'Dinghi', 'Country boat'], correctIndex: 1, explanation: 'The traditional Kerala houseboat is called "Kettuvallam" (literally "boat tied with ropes"). These were originally used for transporting rice and spices through the backwaters. Modern kettuvallams are converted into luxury houseboats for tourists. The backwaters of Alappuzha (Alleppey) and Kumarakom are the most popular destinations.', source: 'Kerala Tourism / Ministry of Tourism', difficulty: 'medium' },
  { slug: 'cul-jaipur-unesco-year', categoryId: 'cat-culture', text: 'Jaipur, the "Pink City," was inscribed as a UNESCO World Heritage Site in which year?', options: ['2016', '2019', '2021', '2023'], correctIndex: 1, explanation: 'Jaipur was inscribed as a UNESCO World Heritage Site in July 2019 under the cultural category. Founded in 1727 by Maharaja Sawai Jai Singh II, Jaipur was designed using Vastu Shastra and Shilpa Shastra principles. The city is known for its pink-coloured buildings, grid layout, and monuments like Hawa Mahal, City Palace, and Jantar Mantar.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-onam-pulikali-tiger-dance', categoryId: 'cat-culture', text: 'Pulikali, the "tiger dance" performed during Onam, is primarily associated with which district of Kerala?', options: ['Thiruvananthapuram', 'Thrissur', 'Ernakulam', 'Kozhikode'], correctIndex: 1, explanation: 'Pulikali (literally "tiger play") is primarily associated with Thrissur district in Kerala. Performers paint themselves as tigers and leopards and dance to traditional percussion music during the Onam festival. The art form originated around 200 years ago during the reign of Maharaja Rama Varma Sakthan Thampuran.', source: 'Kerala Tourism / Ministry of Culture', difficulty: 'hard' },
  { slug: 'cul-sattriya-sankardev-15th', categoryId: 'cat-culture', text: 'Sattriya, the 8th classical dance form of India, was created by which saint in the 15th-16th century?', options: ['Sri Sankardev (Srimanta Sankaradeva)', 'Madhavdev', 'Sri Aurobindo', 'Swami Vivekananda'], correctIndex: 0, explanation: 'Sattriya was created by Srimanta Sankaradeva (1449-1568), a 15th-16th century Vaishnava saint and social reformer of Assam. It originated in the "sattras" (Vaishnava monasteries) of Assam. The Sangeet Natak Akademi recognised Sattriya as the 8th classical dance form in 2000. It was originally performed by male monks.', source: 'Sangeet Natak Akademi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-thanjavur-brihadeshwara-unesco-year', categoryId: 'cat-culture', text: 'The Brihadeshwara Temple at Thanjavur was inscribed as a UNESCO World Heritage Site in which year?', options: ['1982', '1987', '1995', '2004'], correctIndex: 1, explanation: 'The Brihadeshwara Temple (Big Temple) at Thanjavur was inscribed as a UNESCO World Heritage Site in 1987. Built by Rajaraja Chola I around 1010 CE, it is one of the largest temples in India. The vimana (tower) is about 66 m tall, and the temple is topped by an 80-ton monolithic dome. The Great Living Chola Temples include Brihadeshwara (Thanjavur), Brihadeshwara (Gangaikondacholapuram), and Airavatesvara (Darasuram).', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-baul-singer-unesco-2008', categoryId: 'cat-culture', text: 'The Baul tradition of Bengal was inscribed on UNESCO\'s Intangible Cultural Heritage list in which year?', options: ['2005', '2008', '2012', '2018'], correctIndex: 1, explanation: 'The Baul tradition was inscribed on UNESCO\'s Representative List of the Intangible Cultural Heritage of Humanity in 2008. Bauls are mystic minstrels from Bengal (West Bengal and Bangladesh) who sing spiritual songs influenced by Hindu Bhakti and Sufi traditions. Notable Baul singers include Lalon Shah and Purna Das Baul.', source: 'UNESCO Intangible Cultural Heritage List / Sangeet Natak Akademi', difficulty: 'medium' },
  { slug: 'cul-jaipur-literature-festival-year', categoryId: 'cat-culture', text: 'The Jaipur Literature Festival, the world\'s largest free literary festival, was first held in which year?', options: ['2004', '2006', '2008', '2010'], correctIndex: 1, explanation: 'The Jaipur Literature Festival (JLF) was first held in 2006. It has grown to become the world\'s largest free literary festival, attracting over 500,000 attendees annually. Held at Diggi Palace, Jaipur, in January, JLF features writers, poets, and thinkers from across the world. Nobel laureates like Orhan Pamuk and the Dalai Lama have participated.', source: 'Jaipur Literature Festival / Ministry of Culture', difficulty: 'hard' },
  { slug: 'cul-modi-mask-chau-state', categoryId: 'cat-culture', text: 'Chhau dance, a UNESCO-recognised martial dance form, is practised in three regional styles. Which state is NOT one of the three?', options: ['Odisha', 'Jharkhand', 'West Bengal', 'Bihar'], correctIndex: 3, explanation: 'Chhau dance is practised in three styles: Seraikella Chhau (Jharkhand), Mayurbhanj Chhau (Odisha), and Purulia Chhau (West Bengal). Bihar is NOT one of the three states. Chhau was inscribed on UNESCO\'s Intangible Cultural Heritage list in 2010. It combines martial arts, acrobatics, and athletic movements with mythological storytelling.', source: 'UNESCO Intangible Cultural Heritage / Sangeet Natak Akademi', difficulty: 'medium' },

  // ═══ cat-economy (10) ═══
  { slug: 'eco-rbi-currency-notes-issue', categoryId: 'cat-economy', text: 'In India, one-rupee notes and coins are issued by which authority (not the RBI)?', options: ['Reserve Bank of India', 'Government of India (Ministry of Finance)', 'State Bank of India', 'Security Printing and Minting Corporation of India'], correctIndex: 1, explanation: 'One-rupee notes and all coins are issued by the Government of India (Ministry of Finance), while currency notes of denomination Rs. 2 and above are issued by the Reserve Bank of India. The one-rupee note bears the signature of the Finance Secretary, while RBI notes bear the Governor\'s signature.', source: 'Reserve Bank of India / Ministry of Finance', difficulty: 'hard' },
  { slug: 'eco-gst-compensation-cess', categoryId: 'cat-economy', text: 'The GST Compensation Cess was introduced to compensate states for revenue loss due to GST. It was originally intended for how many years?', options: ['3 years (2017-2020)', '5 years (2017-2022)', '7 years (2017-2024)', '10 years (2017-2027)'], correctIndex: 1, explanation: 'The GST Compensation Cess was originally intended for 5 years (2017-2022) to compensate states for revenue losses from GST implementation. The cess was extended beyond 2022 (initially till March 2026) to repay the loans taken by the Centre during COVID-19 to pay states their compensation dues.', source: 'GST Council / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-lic-of-india-assets', categoryId: 'cat-economy', text: 'Life Insurance Corporation of India (LIC) is the largest insurance company in India. Its total assets (as of 2023-24) are approximately how much?', options: ['About Rs. 10 lakh crore', 'About Rs. 25 lakh crore', 'About Rs. 45+ lakh crore', 'About Rs. 100 lakh crore'], correctIndex: 2, explanation: 'LIC\'s total assets were approximately Rs. 45+ lakh crore as of FY 2023-24. LIC was established on 1 September 1956 by nationalising 245 private insurance companies. It has over 290 million policyholders. LIC\'s IPO in May 2022 was India\'s largest at approximately Rs. 21,000 crore.', source: 'Life Insurance Corporation of India / IRDAI', difficulty: 'hard' },
  { slug: 'eco-india-startups-unicorn-count', categoryId: 'cat-economy', text: 'As of 2024, India has approximately how many "unicorn" startups (privately held companies valued at $1 billion or more)?', options: ['About 25', 'About 50', 'About 100+', 'About 200'], correctIndex: 2, explanation: 'As of 2024, India has approximately 100+ unicorn startups (valued at $1 billion+). India has the 3rd-largest unicorn ecosystem after the US and China. Notable Indian unicorns include Flipkart, Paytm, BYJU\'S, Ola, Zomato, Swiggy, and Razorpay. Bengaluru, Delhi NCR, and Mumbai are the top startup hubs.', source: 'NASSCOM / Ministry of Commerce and Industry', difficulty: 'medium' },
  { slug: 'eco-rbi-repo-rate-2024', categoryId: 'cat-economy', text: 'What was the RBI repo rate as of mid-2024 (approximately)?', options: ['4.00%', '5.15%', '6.50%', '8.00%'], correctIndex: 2, explanation: 'As of mid-2024, the RBI repo rate was 6.50%. The RBI\'s Monetary Policy Committee (MPC) had kept the rate unchanged since April 2023 (after raising it from 4.00% to 6.50% between May 2022 and February 2023 to combat inflation). The repo rate is the rate at which the RBI lends to commercial banks.', source: 'Reserve Bank of India / Monetary Policy Committee', difficulty: 'medium' },
  { slug: 'eco-fdi-equity-inflows-2024', categoryId: 'cat-economy', text: 'India\'s total FDI (Foreign Direct Investment) equity inflows since the beginning of FDI policy (from April 2000 to March 2024) are approximately how much?', options: ['About $100 billion', 'About $250 billion', 'About $500 billion', 'About $950+ billion'], correctIndex: 3, explanation: 'India\'s cumulative FDI equity inflows from April 2000 to March 2024 are approximately $950+ billion. The top source countries are Mauritius, Singapore, USA, Netherlands, and Japan. The top sectors are services, computer software, telecommunications, and trading. The DPIIT (Department for Promotion of Industry and Internal Trade) tracks FDI data.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / Ministry of Commerce', difficulty: 'hard' },
  { slug: 'eco-india-foodgrain-production-2024', categoryId: 'cat-economy', text: 'India\'s foodgrain production in 2023-24 (estimated) is approximately how many million tonnes?', options: ['About 200 MT', 'About 280-330 MT', 'About 400 MT', 'About 500 MT'], correctIndex: 1, explanation: 'India\'s foodgrain production in 2023-24 (3rd advance estimates) was approximately 328.9 million tonnes (MT). India is the world\'s second-largest producer of rice and wheat (after China). Rice is the largest foodgrain crop (about 137 MT), followed by wheat (about 113 MT). India is also the world\'s largest producer of milk, pulses, and jute.', source: 'Ministry of Agriculture and Farmers Welfare / Directorate of Economics and Statistics', difficulty: 'medium' },
  { slug: 'eco-india-milk-production-world', categoryId: 'cat-economy', text: 'India is the largest producer of milk in the world. What is India\'s approximate annual milk production (as of 2023-24)?', options: ['About 100 million tonnes', 'About 230 million tonnes', 'About 300 million tonnes', 'About 500 million tonnes'], correctIndex: 1, explanation: 'India is the world\'s largest milk producer with approximately 230 million tonnes annually (2023-24). India accounts for about 24% of global milk production. Operation Flood (launched in 1970 by Verghese Kurien, the "Father of the White Revolution") made India the world\'s largest milk producer. The per capita availability is about 459 grams/day.', source: 'Ministry of Fisheries, Animal Husbandry and Dairying / NDDB', difficulty: 'medium' },
  { slug: 'eco-gst-returns-gstr-1-purpose', categoryId: 'cat-economy', text: 'Under GST, what is the purpose of GSTR-1 (the monthly/quarterly return)?', options: ['It reports the total tax paid', 'It reports details of all outward supplies (sales) made by the taxpayer', 'It reports all purchases and input tax credit', 'It is the final annual return'], correctIndex: 1, explanation: 'GSTR-1 is a monthly or quarterly return that reports details of all outward supplies (sales) made by a registered taxpayer. It includes invoice-level details of sales to registered and unregistered buyers. GSTR-1 is filed by the 11th of the following month (for monthly filers). It enables auto-population of recipients\' GSTR-2B for input tax credit claims.', source: 'GST Council / CBIC (Central Board of Indirect Taxes and Customs)', difficulty: 'medium' },
  { slug: 'eco-india-external-debt-2024', categoryId: 'cat-economy', text: 'India\'s total external debt (as of March 2024) was approximately how much?', options: ['About $200 billion', 'About $400 billion', 'About $663 billion', 'About $1,000 billion'], correctIndex: 2, explanation: 'India\'s total external debt was approximately $663.8 billion as of March 2024 (end of FY 2023-24). The largest component was commercial borrowings (about 33%), followed by NRI deposits (about 23%). The debt-to-GDP ratio was approximately 18.7%. The US dollar-denominated debt accounted for about 53.4% of total external debt.', source: 'Ministry of Finance / Reserve Bank of India', difficulty: 'hard' },

  // ═══ cat-environment (10) ═══
  { slug: 'env-cop28-india-green-hydrogen-mission', categoryId: 'cat-environment', text: 'India launched the National Green Hydrogen Mission in 2023 with what target for green hydrogen production by 2030?', options: ['1 MMT (million metric tonnes)', '3 MMT', '5 MMT', '10 MMT'], correctIndex: 2, explanation: 'The National Green Hydrogen Mission, launched on 4 January 2023 with an outlay of Rs. 19,744 crore, aims to produce 5 MMT (million metric tonnes) of green hydrogen annually by 2030. It also targets 125 GW of renewable energy capacity for green hydrogen production. This would help decarbonise hard-to-abate sectors like steel, fertilisers, and refineries.', source: 'Ministry of New and Renewable Energy (MNRE)', difficulty: 'medium' },
  { slug: 'env-tiger-population-global-share', categoryId: 'cat-environment', text: 'India hosts approximately what percentage of the world\'s wild tiger population?', options: ['About 25%', 'About 50%', 'About 75%', 'About 90%'], correctIndex: 2, explanation: 'India hosts approximately 75% of the world\'s wild tiger population. The 2022 tiger census reported approximately 3,167 tigers in India (up from 2,967 in 2018). India has 55 tiger reserves. St. Petersburg Tiger Summit (2010) set a target of doubling wild tigers by 2022 — India achieved this (Tx2) in 2019.', source: 'National Tiger Conservation Authority (NTCA) / Global Tiger Forum', difficulty: 'medium' },
  { slug: 'env-leopard-population-india-2018', categoryId: 'cat-environment', text: 'According to the "Status of Leopards in India" report (2018, released 2021), India\'s leopard population is approximately how many?', options: ['About 3,000', 'About 7,000', 'About 12,852', 'About 20,000'], correctIndex: 2, explanation: 'The "Status of Leopards in India" report (based on 2018 data, released 2021) estimated approximately 12,852 leopards in India. Madhya Pradesh (3,421) has the most leopards, followed by Karnataka (1,783) and Maharashtra (1,690). Leopards are listed as "Vulnerable" on the IUCN Red List.', source: 'Ministry of Environment, Forest and Climate Change / Wildlife Institute of India', difficulty: 'hard' },
  { slug: 'env-peat-india-wetland-conservation-rivers', categoryId: 'cat-environment', text: 'The East Kolkata Wetlands, a Ramsar Site, are famous for what unique ecological practice?', options: ['Tiger conservation', 'Natural sewage treatment using wastewater aquaculture (fish farming)', 'Mangrove restoration', 'Solar energy generation'], correctIndex: 1, explanation: 'The East Kolkata Wetlands (designated a Ramsar Site in 2002) are famous for natural sewage treatment using wastewater aquaculture — the world\'s largest integrated wastewater treatment and fish farming system. Sewage from Kolkata is naturally treated through a series of shallow fish ponds (bheris) before reaching the river, producing about 13,000 tonnes of fish annually.', source: 'Ramsar Convention Secretariat / Ministry of Environment', difficulty: 'hard' },
  { slug: 'env-solar-rooftop-potential-india', categoryId: 'cat-environment', text: 'India\'s total rooftop solar potential is estimated at approximately how many gigawatts (GW)?', options: ['About 50 GW', 'About 100 GW', 'About 200 GW', 'About 796 GW'], correctIndex: 3, explanation: 'India\'s total rooftop solar potential is estimated at approximately 796 GW (according to a 2022 study by the Council on Energy, Environment and Water, CEEW). Despite this massive potential, India had installed only about 11 GW of rooftop solar capacity by early 2024. The PM Surya Ghar scheme aims to install rooftop solar on 10 million households.', source: 'Ministry of New and Renewable Energy (MNRE) / CEEW', difficulty: 'hard' },
  { slug: 'env-cop15-biodiversity-india', categoryId: 'cat-environment', text: 'At COP15 (2022, Kunming-Montreal), the Global Biodiversity Framework was adopted. What is the "30x30" target?', options: ['30% emissions reduction by 2030', 'Protect 30% of land and sea by 2030', 'Plant 30 billion trees by 2030', '30% renewable energy by 2030'], correctIndex: 1, explanation: 'The "30x30" target from the Kunming-Montreal Global Biodiversity Framework (adopted at COP15 in December 2022) calls for protecting 30% of the world\'s land and 30% of marine areas by 2030. India is a party to the Convention on Biological Diversity. India currently has about 5% of its land area under Protected Areas.', source: 'UN Convention on Biological Diversity / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-air-quality-ncap-cities', categoryId: 'cat-environment', text: 'The National Clean Air Programme (NCAP), launched in 2019, aims to reduce PM pollution in how many cities (initially)?', options: ['24 cities', '60 cities', '102 cities', '132 cities'], correctIndex: 3, explanation: 'The National Clean Air Programme (NCAP), launched in January 2019, initially targeted 102 non-attainment cities (later expanded to 131 cities in 2022). It aims to reduce PM2.5 and PM10 levels by 20-30% by 2024 (baseline 2017). The programme includes city-specific action plans, air quality monitoring, and source apportionment studies.', source: 'Ministry of Environment, Forest and Climate Change / CPCB', difficulty: 'hard' },
  { slug: 'env-wildlife-crocodile-conservation', categoryId: 'cat-environment', text: 'The Madras Crocodile Bank Trust, a major reptile conservation centre, is located in which state?', options: ['Kerala', 'Tamil Nadu', 'Karnataka', 'Andhra Pradesh'], correctIndex: 1, explanation: 'The Madras Crocodile Bank Trust (MCBT), also known as the Crocodile Bank, is located near Chennai, Tamil Nadu. Founded in 1976 by Romulus Whitaker (founder of the Madras Snake Park), it breeds endangered crocodile species, including the gharial, mugger, and saltwater crocodile. It also houses the Agumbe Rainforest Research Station for king cobra conservation.', source: 'Ministry of Environment, Forest and Climate Change / Tamil Nadu Forest Department', difficulty: 'medium' },
  { slug: 'env-clean-river-cauvery-mahanadi-dispute', categoryId: 'cat-environment', text: 'The Mahanadi river is a subject of water-sharing dispute between which two states?', options: ['Odisha and Chhattisgarh', 'Odisha and Jharkhand', 'Chhattisgarh and Madhya Pradesh', 'Odisha and West Bengal'], correctIndex: 0, explanation: 'The Mahanadi river water-sharing dispute is between Odisha (downstream) and Chhattisgarh (upstream). Odisha has objected to Chhattisgarh\'s construction of dams and barrages on the Mahanadi, claiming it reduces water flow during non-monsoon months. The Mahanadi Water Disputes Tribunal was constituted in 2018 to adjudicate.', source: 'Ministry of Jal Shakti / Mahanadi Water Disputes Tribunal', difficulty: 'hard' },
  { slug: 'env-single-use-plastic-ban-items', categoryId: 'cat-environment', text: 'From 1 July 2022, India banned single-use plastic items. How many items were initially identified for the ban?', options: ['5 items', '12 items', '19 items', '50 items'], correctIndex: 2, explanation: 'From 1 July 2022, India banned 19 identified single-use plastic items with low utility and high littering potential, per the Plastic Waste Management (Amendment) Rules, 2022. These include plastic cutlery, earbuds with plastic sticks, plastic flags, candy sticks, ice-cream sticks, and polystyrene (thermocol) for decoration. The ban does not cover all plastic products.', source: 'Ministry of Environment, Forest and Climate Change / CPCB', difficulty: 'medium' },

  // ═══ cat-art (10) ═══
  { slug: 'art-rabindranath-tagore-national-anthem-composer', categoryId: 'cat-art', text: 'Rabindranath Tagore composed the national anthem of India ("Jana Gana Mana"). Which other country\'s national anthem did he also compose?', options: ['India only', 'India and Bangladesh ("Amar Sonar Bangla")', 'India and Sri Lanka', 'India and Nepal'], correctIndex: 1, explanation: 'Rabindranath Tagore composed the national anthems of two countries: India ("Jana Gana Mana") and Bangladesh ("Amar Sonar Bangla"). He is the only person to have composed the national anthems of two different sovereign nations. "Amar Sonar Bangla" was adopted as Bangladesh\'s national anthem in 1971. Tagore also wrote the lyrics for Sri Lanka\'s national anthem ("Sri Lanka Matha"), but the music was composed by Ananda Samarakoon (Tagore\'s student).', source: 'Ministry of Culture / Sahitya Akademi', difficulty: 'medium' },
  { slug: 'art-mughal-painting-hamzanama', categoryId: 'cat-art', text: 'The "Hamzanama," a famous Mughal painting commission, was commissioned by which emperor?', options: ['Humayun', 'Akbar', 'Jahangir', 'Shah Jahan'], correctIndex: 1, explanation: 'The "Hamzanama" (Adventures of Hamza) was commissioned by Emperor Akbar (c. 1557-1572). It was a massive project of about 1,400 large paintings on cloth, depicting the adventures of Amir Hamza (uncle of Prophet Muhammad). About 27 folios survive today. The project involved over 100 artists and took about 15 years, fusing Persian, Indian, and Islamic painting traditions.', source: 'National Museum, New Delhi / Victoria and Albert Museum, London', difficulty: 'hard' },
  { slug: 'art-pandit-bhimsen-joshi-gharana', categoryId: 'cat-art', text: 'Pandit Bhimsen Joshi, one of India\'s greatest Hindustani classical vocalists, belonged to which gharana (musical lineage)?', options: ['Gwalior Gharana', 'Kirana Gharana', 'Agra Gharana', 'Jaipur-Atrauli Gharana'], correctIndex: 1, explanation: 'Pandit Bhimsen Joshi (1922-2011) belonged to the Kirana Gharana, founded by Abdul Karim Khan. He was a legendary exponent of Hindustani khayal singing. He received the Bharat Ratna (India\'s highest civilian honour) in 2009 — the first Hindustani classical vocalist to receive it. He was also known for his devotional bhajans and the "Mile Sur Mera Tumhara" national integration song.', source: 'Sangeet Natak Akademi / Ministry of Culture', difficulty: 'medium' },
  { slug: 'art-jaipur-amber-fort-mirror-palace', categoryId: 'cat-art', text: 'The "Sheesh Mahal" (Mirror Palace) is a famous feature of which fort?', options: ['Amer Fort, Jaipur', 'Mehrangarh Fort, Jodhpur', 'City Palace, Udaipur', 'Jaisalmer Fort'], correctIndex: 0, explanation: 'The Sheesh Mahal (Mirror Palace) is located inside Amer Fort (Amber Fort), Jaipur. It was built by Raja Man Singh in the 16th century and completed by Mirza Raja Jai Singh. The walls and ceiling are covered with thousands of tiny mirrors (glass tiles). A single candle lit inside would reflect off the mirrors, illuminating the entire hall. Amer Fort is part of the UNESCO-listed "Hill Forts of Rajasthan."', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'art-madhubani-painting-origin', categoryId: 'cat-art', text: 'Madhubani painting, a traditional art form, originates from which Indian state?', options: ['Bihar', 'Uttar Pradesh', 'Jharkhand', 'West Bengal'], correctIndex: 0, explanation: 'Madhubani painting (Mithila painting) originates from the Mithila region of Bihar, particularly the Madhubani district. It was traditionally created by women on walls and floors for festivals and weddings. The art form uses natural dyes and pigments and features geometric patterns, deities, and nature motifs. It received GI (Geographical Indication) tag status.', source: 'Ministry of Culture / Bihar Tourism', difficulty: 'easy' },
  { slug: 'art-carnatic-music-trinity', categoryId: 'cat-art', text: 'The "Carnatic Music Trinity" consists of three composers who lived in the 18th century in Tamil Nadu. Who are they?', options: ['Muthuswami Dikshitar, Syama Sastri, and Tyagaraja', 'Purandara Dasa, Kanaka Dasa, and Tyagaraja', 'Swathi Thirunal, Annamacharya, and Tyagaraja', 'Muthuswami Dikshitar, Syama Sastri, and Purandara Dasa'], correctIndex: 0, explanation: 'The Carnatic Music Trinity are Muthuswami Dikshitar (1775-1835), Syama Sastri (1762-1827), and Tyagaraja (1767-1847). All three lived in Tiruvarur, Tamil Nadu, in the 18th century. They revolutionised Carnatic music and composed thousands of krithis (compositions). Tyagaraja\'s "Pancharatna Kritis" (Five Gems) are widely performed. Purandara Dasa (1484-1564) is called the "Father of Carnatic Music."', source: 'Sangeet Natak Akademi / Music Academy, Chennai', difficulty: 'hard' },
  { slug: 'art-ancient-indian-architecture-stupa', categoryId: 'cat-art', text: 'The Great Stupa at Sanchi, a UNESCO World Heritage Site, was originally commissioned by which emperor?', options: ['Ashoka', 'Kanishka', 'Harsha', 'Chandragupta Maurya'], correctIndex: 0, explanation: 'The Great Stupa at Sanchi (Madhya Pradesh) was originally commissioned by Emperor Ashoka in the 3rd century BCE. It is one of the oldest stone structures in India and a UNESCO World Heritage Site. The stupa contains relics of the Buddha. Its four toranas (gateways) were added later (1st century BCE - 1st century CE) by the Satavahanas and feature intricate carvings of the Buddha\'s life.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'art-mughal-architecture-red-fort-delhi-builder', categoryId: 'cat-art', text: 'The Red Fort (Lal Qila) in Delhi was built by which Mughal Emperor?', options: ['Akbar', 'Shah Jahan', 'Aurangzeb', 'Babur'], correctIndex: 1, explanation: 'The Red Fort (Lal Qila) was built by Emperor Shah Jahan (r. 1628-1658) between 1639 and 1648 as the new capital of the Mughal Empire (Shahjahanabad). It is made of red sandstone and is a UNESCO World Heritage Site. The Prime Minister of India hoists the national flag from its ramparts on Independence Day (15 August) each year.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'easy' },
  { slug: 'art-classical-dance-mohiniyattam-state', categoryId: 'cat-art', text: 'Mohiniyattam, a classical dance form, originates from which Indian state?', options: ['Kerala', 'Tamil Nadu', 'Karnataka', 'Andhra Pradesh'], correctIndex: 0, explanation: 'Mohiniyattam is a classical dance form from Kerala. The name comes from "Mohini" (the female enchantress avatar of Vishnu) and "attam" (dance). It is characterised by gentle, graceful, and lyrical movements, typically performed solo by women. The Sangeet Natak Akademi recognised it as one of India\'s 8 classical dance forms. It evolved in the temples of Kerala.', source: 'Sangeet Natak Akademi / Kerala Sangeetha Nataka Akademi', difficulty: 'medium' },
  { slug: 'art-bharatanatyam-geometrical-symbol', categoryId: 'cat-art', text: 'In Bharatanatyam, the basic geometric posture from which all movements begin is called what?', options: ['Tandava', 'Araimandi (half-sitting posture)', 'Abhinaya', 'Tatta'], correctIndex: 1, explanation: 'Araimandi (literally "half-sitting") is the basic geometric posture in Bharatanatyam. The dancer sits half-way down, with knees turned outward, feet pointing outward, and the distance between the feet approximately equal to the distance between the head and navel. It is said to resemble a triangle. This posture is the foundation for all movements and steps (adavus) in Bharatanatyam.', source: 'Sangeet Natak Akademi / Kalakshetra Foundation', difficulty: 'hard' },

  // ═══ cat-edu (10) ═══
  { slug: 'edu-world-universities-debating-2024-qs', categoryId: 'cat-edu', text: 'In the QS World University Rankings 2025, which Indian institution ranked highest?', options: ['IIT Bombay', 'IIT Delhi', 'IISc Bengaluru', 'IIT Madras'], correctIndex: 0, explanation: 'In the QS World University Rankings 2025, IIT Bombay ranked highest among Indian institutions (at rank 118 globally). IIT Delhi ranked 150th and IISc Bengaluru ranked 211th. In the NIRF (National Institutional Ranking Framework) 2024 (domestic rankings), IIT Madras ranked first overall in India.', source: 'QS World University Rankings / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-iisc-establishment', categoryId: 'cat-edu', text: 'The Indian Institute of Science (IISc), one of India\'s premier research institutions, was established in which year?', options: ['1898', '1909', '1934', '1951'], correctIndex: 1, explanation: 'IISc was established in 1909 in Bangalore (Bengaluru), following a meeting between Jamsetji Nusserwanji Tata and Swami Vivekananda in 1898 on a ship to Chicago. Tata\'s vision was to create a university of science. Lord Curzon (Viceroy) laid the foundation stone in 1898. The Krishnarajasendra Wodeyar IV, Maharaja of Mysore, donated 371 acres of land. IISc is consistently ranked among India\'s top research institutions.', source: 'Indian Institute of Science / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-akul-gandhi-national-rousse', categoryId: 'cat-edu', text: 'The Government of India launched the PM-SHRI (PM Schools for Rising India) scheme in which year, aiming to upgrade how many schools?', options: ['2020, 10,000 schools', '2021, 15,000 schools', '2022, 14,500+ schools', '2023, 25,000 schools'], correctIndex: 2, explanation: 'PM-SHRI (PM Schools for Rising India) was launched on 5 September 2022 (Teachers\' Day). It aims to upgrade 14,500+ existing schools to model schools with modern infrastructure, innovative pedagogy, and green building standards. The scheme targets students from pre-primary to Class 12, with an outlay of approximately Rs. 27,360 crore for 5 years (2022-23 to 2026-27).', source: 'Ministry of Education / PM-SHRI portal', difficulty: 'medium' },
  { slug: 'edu-digi-locker-documents-count', categoryId: 'cat-edu', text: 'DigiLocker, the Government of India\'s digital document wallet, had issued approximately how many documents by 2024 (cumulative)?', options: ['About 100 million', 'About 500 million', 'About 6+ billion', 'About 10 billion'], correctIndex: 2, explanation: 'DigiLocker had issued approximately 6+ billion (600+ crore) documents by 2024, with over 270 million registered users. Documents include Aadhaar, driving licence, vehicle registration, educational certificates, CBSE results, and vaccination certificates. DigiLocker was launched in February 2015 under the Digital India programme and is legally equivalent to original documents under the IT Act, 2000.', source: 'Ministry of Electronics and IT (MeitY) / NeGD / DigiLocker', difficulty: 'hard' },
  { slug: 'edu-nep-2020-multidisciplinary-target', categoryId: 'cat-edu', text: 'NEP 2020 aims to make higher education institutions multidisciplinary by which year?', options: ['2025', '2030', '2035', '2040'], correctIndex: 2, explanation: 'NEP 2020 aims to transform all higher education institutions into multidisciplinary institutions by 2030, and by 2040, all institutions should aim to be multidisciplinary. The target is to increase the Gross Enrolment Ratio (GER) in higher education from about 26.3% (2018) to 50% by 2035. NEP 2020 was approved by the Union Cabinet on 29 July 2020, replacing NEP 1986.', source: 'Ministry of Education / National Education Policy 2020', difficulty: 'medium' },
  { slug: 'edu-cuet-ug-purpose', categoryId: 'cat-edu', text: 'CUET (Common University Entrance Test) was introduced in which year for admission to central universities?', options: ['2019', '2020', '2022', '2024'], correctIndex: 2, explanation: 'CUET-UG was introduced in 2022 by the National Testing Agency (NTA) for admission to undergraduate programs in all 45+ central universities. CUET replaced multiple university-specific entrance exams, providing a single-window for admissions. The first CUET-UG in 2022 had approximately 14.9 lakh (1.49 million) registered candidates. CUET-PG for postgraduate courses was also launched in 2022.', source: 'National Testing Agency (NTA) / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-all-india-medical-seats-2024', categoryId: 'cat-edu', text: 'As of 2024, India has approximately how many MBBS seats across all medical colleges?', options: ['About 50,000', 'About 75,000', 'About 1,08,000+', 'About 1,50,000'], correctIndex: 2, explanation: 'As of 2024, India has approximately 1,08,000+ MBBS seats across about 706 medical colleges (government + private). This includes about 280+ government medical colleges (~48,000 seats) and 300+ private medical colleges (~43,000 seats). AIIMS and other central institutions add about 1,500+ seats. India added 10,000+ MBBS seats in 2023-24 alone.', source: 'National Medical Commission (NMC) / Ministry of Health', difficulty: 'medium' },
  { slug: 'edu-stree-nidhi-credit-loan', categoryId: 'cat-edu', text: 'PM-USHA (Pradhan Mantri Uchchatar Shiksha Abhiyan), launched in 2023, merges how many existing schemes?', options: ['2 schemes', '3 schemes', '4 schemes', '5 schemes'], correctIndex: 1, explanation: 'PM-USHA (Pradhan Mantri Uchchatar Shiksha Abhiyan), approved in June 2023, merges 3 existing schemes: Rashtriya Uchchatar Shiksha Abhiyan (RUSA), National Higher Education Mission (NMEICT), and the Scheme of Apprenticeship. It has an outlay of Rs. 12,926 crore for 2023-26 and focuses on equity, access, quality, and employability in higher education.', source: 'Ministry of Education / Department of Higher Education', difficulty: 'hard' },
  { slug: 'edu-indian-foundation-survey-2023', categoryId: 'cat-edu', text: 'India\'s first "Foundational Learning Study" (2022), conducted by NCERT, assessed children in which classes?', options: ['Class 1 only', 'Classes 1-2', 'Classes 1-3 (Foundational Stage)', 'Classes 3-5'], correctIndex: 2, explanation: 'The Foundational Learning Study (March 2022), conducted by NCERT, assessed foundational literacy and numeracy in Class 3 students across India. About 86,000 Class 3 students from 10,000 schools across 20 languages were assessed. The study found that approximately 37% of students were at the "below partial" level in literacy and 11% lacked basic numeracy skills. This informed the NIPUN Bharat Mission (National Initiative for Proficiency in Reading with Understanding and Numeracy), launched in 2021, targeting foundational learning by 2026-27.', source: 'NCERT / Ministry of Education / NIPUN Bharat Mission', difficulty: 'hard' },
  { slug: 'edu-vocational-education-samagr-shiksha', categoryId: 'cat-edu', text: 'Under the Samagra Shiksha Abhiyan, vocational education is introduced from which class?', options: ['Class 6', 'Class 9', 'Class 11', 'Class 8'], correctIndex: 1, explanation: 'Under Samagra Shiksha (an overarching programme for school education from pre-school to Class 12), vocational education is introduced from Class 9. Students can choose from vocational modules like IT/ITeS, Retail, Automotive, Healthcare, Beauty and Wellness, etc. NEP 2020 further emphasizes vocational education from Class 6 onwards, aiming to expose 50% of students to vocational education by 2025.', source: 'Ministry of Education / Samagra Shiksha / NCERT', difficulty: 'medium' },
];

async function main() {
  console.log('=== Batch 5 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
